// Configure local/YouTube video pairs before enabling. Never put credentials here.
const mappings = [];
const seen = new Set();
const today = new Date();
const end = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate() - 3));
const start = new Date(end.getTime() - 13 * 86400000);
const iso = d => d.toISOString().slice(0, 10);
return mappings.map(m => {
  if (!/^[0-9a-f]{32}$/.test(m.video_id) || !/^[A-Za-z0-9_-]{11}$/.test(m.youtube_id) || seen.has(m.video_id)) throw new Error('invalid or duplicate video mapping');
  seen.add(m.video_id);
  return {json: {...m, start: iso(start), end: iso(end)}};
});

const inputs = $input.all();
const queries = $('Prepare queries').all();
if (inputs.length !== queries.length) throw new Error('report count mismatch');
const mapping = {views:'views', estimatedMinutesWatched:'estimated_minutes_watched', averageViewDuration:'average_view_duration_s', averageViewPercentage:'average_view_percentage', likes:'likes', comments:'comments', shares:'shares', subscribersGained:'subscribers_gained'};
const out = [];
for (let i=0; i<inputs.length; i++) {
  const report=inputs[i].json, q=queries[i].json;
  if (!Array.isArray(report.columnHeaders)) throw new Error('missing column headers');
  const names=report.columnHeaders.map(x=>x.name);
  if (!names.includes('day') || !names.includes('views') || new Set(names).size !== names.length) throw new Error('invalid columns');
  if (report.rows !== undefined && !Array.isArray(report.rows)) throw new Error('invalid rows');
  const days=new Set();
  for (const row of (report.rows || [])) {
    if (!Array.isArray(row) || row.length !== names.length) throw new Error('invalid row');
    const day=row[names.indexOf('day')];
    if (typeof day !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(day) || day < q.start || day > q.end || days.has(day)) throw new Error('invalid day');
    days.add(day);
    const metric={video_id:q.video_id, date:day};
    for (let j=0; j<names.length; j++) if (mapping[names[j]]) {
      const value=row[j];
      if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) throw new Error('invalid metric');
      metric[mapping[names[j]]]=value;
    }
    out.push({json:metric});
  }
}
return out;
